import{_ as a,o,c as t,a2 as r}from"./chunks/framework.BXzK3EA4.js";const c=JSON.parse('{"title":"Bare Metal Cloud Control Panel User Guide","description":"","frontmatter":{"title":"Bare Metal Cloud Control Panel User Guide"},"headers":[],"relativePath":"operations-knowledge-base/baremetal/bare-metal-cloud-control-panel-user-guide.md","filePath":"operations-knowledge-base/baremetal/bare-metal-cloud-control-panel-user-guide.md","lastUpdated":1794309341000}'),i={name:"operations-knowledge-base/baremetal/bare-metal-cloud-control-panel-user-guide.md"};function n(s,e,l,d,u,p){return o(),t("div",null,[...e[0]||(e[0]=[r('<h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>This document introduces the main functional modules and basic operations available in the Bare Metal Cloud Control Panel, helping users quickly become familiar with the management interface.</p><p>For features such as <strong>Upgrade/Downgrade</strong>, <strong>Snapshots</strong>, and <strong>Security Groups</strong>, this guide provides only a brief overview. Please refer to the corresponding knowledge base articles for detailed instructions.</p><p><strong>Applicable Product:</strong> Bare Metal Cloud</p><hr><h2 id="_1-accessing-the-bare-metal-cloud-control-panel" tabindex="-1">1. Accessing the Bare Metal Cloud Control Panel <a class="header-anchor" href="#_1-accessing-the-bare-metal-cloud-control-panel" aria-label="Permalink to &quot;1. Accessing the Bare Metal Cloud Control Panel&quot;">​</a></h2><ol><li>Log in to the <strong>Raksmart Client Portal</strong>.</li><li>Navigate to <strong>Product Management</strong> → <strong>Bare Metal Cloud</strong>.</li><li>Locate the Bare Metal Cloud server you want to manage.</li><li>Click the product name to enter the server management page.</li></ol><p>The following functional modules are available at the top of the page:</p><ul><li>Management</li><li>Configuration</li><li>Monitoring</li><li>Additional Features</li><li>Applications</li><li>Snapshots</li></ul><hr><h2 id="_2-management" tabindex="-1">2. Management <a class="header-anchor" href="#_2-management" aria-label="Permalink to &quot;2. Management&quot;">​</a></h2><p>The <strong>Management</strong> page provides the most commonly used server management functions, including power control, system maintenance, and remote management.</p><h2 id="refresh-status" tabindex="-1">Refresh Status <a class="header-anchor" href="#refresh-status" aria-label="Permalink to &quot;Refresh Status&quot;">​</a></h2><p>Click <strong>Refresh Status</strong> to update the current operating status of the server.</p><p>Typical use cases:</p><ul><li>Check whether the server is powered on</li><li>Verify whether a shutdown or reboot operation has completed</li></ul><hr><h2 id="power-on" tabindex="-1">Power On <a class="header-anchor" href="#power-on" aria-label="Permalink to &quot;Power On&quot;">​</a></h2><p>When the server is powered off, click <strong>Power On</strong> to start the server.</p><p>Typical use cases:</p><ul><li>Restart a powered-off server</li><li>Resume services after maintenance</li></ul><hr><h2 id="shut-down" tabindex="-1">Shut Down <a class="header-anchor" href="#shut-down" aria-label="Permalink to &quot;Shut Down&quot;">​</a></h2><p>Click <strong>Shut Down</strong> to perform a normal operating system shutdown.</p><p>Recommended before:</p><ul><li>Hardware maintenance</li><li>System configuration changes</li><li>Long-term server downtime</li></ul><blockquote><p><strong>Note:</strong></p><p>Stop running services or ensure that no critical tasks are in progress before shutting down the server to avoid service interruption.</p></blockquote><hr><h2 id="reboot" tabindex="-1">Reboot <a class="header-anchor" href="#reboot" aria-label="Permalink to &quot;Reboot&quot;">​</a></h2><p>Click <strong>Reboot</strong> to restart the server normally.</p><p>Typical use cases:</p><ul><li>Apply system configuration changes</li><li>Complete system updates</li><li>Recover from system issues</li></ul><hr><h2 id="force-power-off" tabindex="-1">Force Power Off <a class="header-anchor" href="#force-power-off" aria-label="Permalink to &quot;Force Power Off&quot;">​</a></h2><p>Click <strong>Force Power Off</strong> to immediately turn off the server.</p><blockquote><p><strong>Warning:</strong></p><p>A force shutdown does not allow the operating system to shut down properly and may result in data loss or file system corruption.</p><p>Use this option only if the server cannot be shut down normally.</p></blockquote><hr><h2 id="vnc-console" tabindex="-1">VNC Console <a class="header-anchor" href="#vnc-console" aria-label="Permalink to &quot;VNC Console&quot;">​</a></h2><p>The VNC Console provides direct access to the server console.</p><p>Even if the network connection is unavailable or SSH/RDP cannot be accessed, you can still manage the server through VNC.</p><p>Common use cases include:</p><ul><li>SSH connection failure</li><li>Remote Desktop (RDP) connection failure</li><li>System boot issues</li><li>Changing the system password</li><li>Entering single-user mode</li><li>Viewing the system boot process</li></ul><p>For detailed instructions, please refer to <a href="/operations-knowledge-base/baremetal/bare-metal-cloud-vnc-console-user-guide.html"><strong>Bare Metal Cloud VNC Console User Guide</strong>.</a></p><hr><h2 id="reset-password" tabindex="-1">Reset Password <a class="header-anchor" href="#reset-password" aria-label="Permalink to &quot;Reset Password&quot;">​</a></h2><p>Use this feature to reset the server&#39;s login password.</p><p>Typical use cases:</p><ul><li>Forgotten login password</li><li>Initial password replacement</li></ul><p>For detailed instructions, please refer to <a href="/operations-knowledge-base/baremetal/bare-metal-cloud-password-change-and-reset-guide.html"><strong>Bare Metal Cloud Password Change and Reset Guide</strong>.</a></p><hr><h2 id="reinstall-operating-system" tabindex="-1">Reinstall Operating System <a class="header-anchor" href="#reinstall-operating-system" aria-label="Permalink to &quot;Reinstall Operating System&quot;">​</a></h2><p>Use this feature to reinstall the operating system.</p><p>Supported operating systems include Linux and Windows (depending on the options available in the control panel).</p><blockquote><p><strong>Warning:</strong></p><p>Reinstalling the operating system will erase all data on the system disk.</p><p>Please back up any important data before proceeding.</p></blockquote><p>For detailed instructions, please refer to <a href="/operations-knowledge-base/baremetal/bare-metal-cloud-os-reinstallation-guide.html"><strong>Bare Metal Cloud OS Reinstallation Guide</strong></a>.</p><hr><h2 id="rescue-mode" tabindex="-1">Rescue Mode <a class="header-anchor" href="#rescue-mode" aria-label="Permalink to &quot;Rescue Mode&quot;">​</a></h2><p>If the operating system cannot boot normally, you can enter Rescue Mode to repair the system or recover data.</p><p>Common use cases include:</p><ul><li>Operating system boot failure</li><li>File system repair</li><li>Boot configuration repair</li><li>Data recovery</li></ul><p>For detailed instructions, please refer to <a href="/operations-knowledge-base/baremetal/bare-metal-cloud-rescue-mode-user-guide.html"><strong>Bare Metal Cloud Rescue Mode User Guide</strong></a>.</p><hr><h2 id="upgrade-downgrade" tabindex="-1">Upgrade / Downgrade <a class="header-anchor" href="#upgrade-downgrade" aria-label="Permalink to &quot;Upgrade / Downgrade&quot;">​</a></h2><p>You can adjust your server resources according to your business requirements.</p><p>Available upgrade or downgrade options depend on your server configuration and may include:</p><ul><li>CPU</li><li>Memory</li><li>Bandwidth</li><li>Traffic</li></ul><p>For detailed instructions, please refer to <a href="/operations-knowledge-base/baremetal/bare-metal-cloud-upgrade-downgrade-guide.html"><strong>Bare Metal Cloud Upgrade/Downgrade Guide</strong></a>.</p><hr><h2 id="_3-configuration" tabindex="-1">3. Configuration <a class="header-anchor" href="#_3-configuration" aria-label="Permalink to &quot;3. Configuration&quot;">​</a></h2><p>The <strong>Configuration</strong> page displays the current server specifications.</p><p>You can view information such as:</p><ul><li>CPU Configuration</li><li>Memory Capacity</li><li>System Disk</li><li>Bandwidth Type</li><li>Bandwidth Size</li><li>Traffic Plan</li><li>DDoS Protection IP (if purchased)</li></ul><p>Use this page to verify your server specifications and network configuration.</p><blockquote><p><strong>Note:</strong></p><p>This page is for viewing configuration information only. Server specifications cannot be modified directly from this page.</p></blockquote><hr><h2 id="_4-monitoring" tabindex="-1">4. Monitoring <a class="header-anchor" href="#_4-monitoring" aria-label="Permalink to &quot;4. Monitoring&quot;">​</a></h2><p>The <strong>Monitoring</strong> page allows you to view the server&#39;s resource usage and monitor its operating status.</p><p>The following monitoring metrics are currently available:</p><ul><li>CPU Usage</li><li>Disk I/O</li><li>Memory Usage</li><li>Network Traffic</li><li>Traffic Statistics</li></ul><p>The monitoring charts help you analyze resource utilization, such as:</p><ul><li>Whether CPU usage remains consistently high</li><li>Whether abnormal disk activity exists</li><li>Whether memory resources are insufficient</li><li>Whether network traffic is abnormal</li></ul><p>For detailed instructions, please refer to <a href="/operations-knowledge-base/baremetal/bare-metal-cloud-monitoring-feature-guide.html"><strong>Bare Metal Cloud Monitoring Guide</strong></a>.</p><hr><h2 id="_5-additional-features" tabindex="-1">5. Additional Features <a class="header-anchor" href="#_5-additional-features" aria-label="Permalink to &quot;5. Additional Features&quot;">​</a></h2><p>The <strong>Additional Features</strong> page is primarily used for managing server network security.</p><p>The following functions are available:</p><ul><li>Create Security Groups</li><li>Manage Security Groups</li><li>Delete Security Groups</li><li>Apply Security Groups to the server</li><li>Remove Security Groups from the server</li></ul><p>Security Groups allow you to control inbound network access and manage firewall rules, improving server security.</p><p>For detailed instructions, please refer to <a href="/operations-knowledge-base/vps/vps-security-group-user-guide.html"><strong>Bare Metal Cloud Security Group Guide</strong></a>.</p><hr><h2 id="_6-applications" tabindex="-1">6. Applications <a class="header-anchor" href="#_6-applications" aria-label="Permalink to &quot;6. Applications&quot;">​</a></h2><p>The <strong>Applications</strong> page is used to manage available system applications or additional features.</p><p>Available applications may vary depending on the product and operating system.</p><p>If no applications are displayed, no further action is required.</p><hr><h2 id="_7-snapshots" tabindex="-1">7. Snapshots <a class="header-anchor" href="#_7-snapshots" aria-label="Permalink to &quot;7. Snapshots&quot;">​</a></h2><p>Snapshots allow you to save the current state of your server for future recovery.</p><p>It is recommended to create a snapshot before:</p><ul><li>Upgrading the operating system</li><li>Installing software</li><li>Modifying important system configurations</li><li>Deploying production services</li></ul><blockquote><p><strong>Note:</strong></p><p>Snapshots are intended for quick system recovery and should not replace regular data backups.</p><p>Important business data should still be backed up independently on a regular basis.</p></blockquote><p>For detailed instructions, please refer to <strong>Bare Metal Cloud Snapshot Guide</strong>.</p><hr><h2 id="_8-frequently-asked-questions" tabindex="-1">8. Frequently Asked Questions <a class="header-anchor" href="#_8-frequently-asked-questions" aria-label="Permalink to &quot;8. Frequently Asked Questions&quot;">​</a></h2><h3 id="q1-why-doesn-t-the-server-shut-down-immediately-after-i-click-shut-down" tabindex="-1">Q1: Why doesn&#39;t the server shut down immediately after I click <strong>Shut Down</strong>? <a class="header-anchor" href="#q1-why-doesn-t-the-server-shut-down-immediately-after-i-click-shut-down" aria-label="Permalink to &quot;Q1: Why doesn&#39;t the server shut down immediately after I click **Shut Down**?&quot;">​</a></h3><p>The server performs a normal operating system shutdown.</p><p>The required time depends on the operating system and currently running services.</p><p>Please wait a few moments and refresh the server status.</p><hr><h3 id="q2-when-should-i-use-force-power-off" tabindex="-1">Q2: When should I use <strong>Force Power Off</strong>? <a class="header-anchor" href="#q2-when-should-i-use-force-power-off" aria-label="Permalink to &quot;Q2: When should I use **Force Power Off**?&quot;">​</a></h3><p>Force Power Off should be used only when the server becomes unresponsive and cannot perform a normal shutdown.</p><p>Under normal circumstances, always use <strong>Shut Down</strong> first.</p><hr><h3 id="q3-will-reinstalling-the-operating-system-delete-my-data" tabindex="-1">Q3: Will reinstalling the operating system delete my data? <a class="header-anchor" href="#q3-will-reinstalling-the-operating-system-delete-my-data" aria-label="Permalink to &quot;Q3: Will reinstalling the operating system delete my data?&quot;">​</a></h3><p>Yes.</p><p>Reinstalling the operating system erases all data on the system disk.</p><p>Please back up important data before reinstalling the operating system.</p><hr><h3 id="q4-what-is-the-difference-between-vnc-and-ssh-or-windows-remote-desktop" tabindex="-1">Q4: What is the difference between VNC and SSH (or Windows Remote Desktop)? <a class="header-anchor" href="#q4-what-is-the-difference-between-vnc-and-ssh-or-windows-remote-desktop" aria-label="Permalink to &quot;Q4: What is the difference between VNC and SSH (or Windows Remote Desktop)?&quot;">​</a></h3><p>SSH and Remote Desktop (RDP) are network-based remote access methods.</p><p>The VNC Console provides direct console access to the server.</p><p>Even if network connectivity is unavailable or SSH/RDP cannot be accessed, you can usually still manage the server through the VNC Console.</p><hr><h3 id="q5-why-can-t-i-modify-cpu-memory-or-bandwidth-from-the-configuration-page" tabindex="-1">Q5: Why can&#39;t I modify CPU, memory, or bandwidth from the Configuration page? <a class="header-anchor" href="#q5-why-can-t-i-modify-cpu-memory-or-bandwidth-from-the-configuration-page" aria-label="Permalink to &quot;Q5: Why can&#39;t I modify CPU, memory, or bandwidth from the Configuration page?&quot;">​</a></h3><p>The <strong>Configuration</strong> page is for viewing your current server specifications only.</p><p>To change server resources, please use the <strong>Upgrade/Downgrade</strong> feature.</p><p>For detailed instructions, please refer to <strong>Bare Metal Cloud Upgrade/Downgrade Guide</strong>.</p>',126)])])}const g=a(i,[["render",n]]);export{c as __pageData,g as default};
